// Removed from index.html in v27.80 (quick-sale). Kept so it can be revisited.
// Full working app as it was: GitHub branch archive/v27.70-before-revamp.

function saleSrchCust(q){
  // works with both old (saleCustDD) and new (saleCustResults) element IDs
  var dd = document.getElementById('saleCustResults') || document.getElementById('saleCustDD');
  if(!dd) return;
  if(!q||q.length<1){dd.innerHTML='';if(dd.style)dd.style.display='none';return;}
  var ql = q.toLowerCase();
  var hits = custs.filter(function(c){
    return (c.name||'').toLowerCase().includes(ql)||
           (c.phone||'').includes(q);
  }).slice(0,8);
  var walkInRow = '<div data-walkin="1" style="background:var(--sf2);border:1.5px dashed var(--bd2);border-radius:var(--rs);padding:10px 12px;margin-bottom:6px;cursor:pointer;display:flex;align-items:center;gap:8px">' +
    '<span style="font-size:18px">&#128100;</span>' +
    '<div><div style="font-size:14px;font-weight:600">Walk-in: &quot;' + q + '&quot;</div>' +
    '<div style="font-size:12px;color:var(--tx3)">Use as one-time name — no customer record needed</div></div></div>';
  if(!hits.length){
    dd.innerHTML=walkInRow;
    if(dd.style)dd.style.display='block';
    return;
  }
  dd.innerHTML = hits.map(function(c){
    return '<div data-cid="'+c.id+'" onclick="pickSaleCust(this.dataset.cid)" style="background:var(--sf2);border:1.5px solid var(--bd2);border-radius:var(--rs);padding:10px 12px;margin-bottom:6px;cursor:pointer">'+
      '<div style="font-size:14px;font-weight:600">'+c.name+'</div>'+
      '<div style="font-size:12px;color:var(--tx3)">'+(c.phone||'no phone')+'</div>'+
    '</div>';
  }).join('');
  dd.innerHTML += walkInRow;
  if(dd.style)dd.style.display='block';
  // Wire walk-in click via delegation
  dd.onclick = function(e){
    var wi = e.target.closest('[data-walkin]');
    if(wi){
      var inp = document.getElementById('saleCustSearch');
      useWalkIn(inp ? inp.value.trim() : q);
    }
  };
}

function pickSaleCust(id){
  saleCustId = id;
  var c = custs.find(function(x){return x.id===id;});
  if(!c)return;
  document.getElementById('saleCustSearch').value = '';
  var ddEl = document.getElementById('saleCustResults') || document.getElementById('saleCustDD');
  if(ddEl){ddEl.innerHTML='';if(ddEl.style)ddEl.style.display='none';}
  var nameEl = document.getElementById('saleCustName'); if(nameEl) nameEl.textContent = c.name;
  var badgeEl = document.getElementById('saleCustSelected') || document.getElementById('saleCustBadge');
  if(badgeEl){badgeEl.style.display='flex';}
}

function useWalkIn(name){
  saleCustId=null;
  saleCustObj={name:name,phone:'',walkIn:true};
  var srchEl=document.getElementById('saleCustSearch');if(srchEl)srchEl.value='';
  var nameEl=document.getElementById('saleCustName');if(nameEl)nameEl.textContent=name+' (walk-in)';
  var badgeEl=document.getElementById('saleCustSelected')||document.getElementById('saleCustBadge');
  if(badgeEl)badgeEl.style.display='flex';
  var ddEl=document.getElementById('saleCustResults')||document.getElementById('saleCustDD');
  if(ddEl){ddEl.innerHTML='';if(ddEl.style)ddEl.style.display='none';}
}

function clearSaleCust(){
  saleCustId = null;
  var srchEl = document.getElementById('saleCustSearch'); if(srchEl) srchEl.value = '';
  var badgeEl = document.getElementById('saleCustSelected') || document.getElementById('saleCustBadge');
  if(badgeEl) badgeEl.style.display = 'none';
  var ddEl = document.getElementById('saleCustResults') || document.getElementById('saleCustDD');
  if(ddEl){ddEl.innerHTML='';if(ddEl.style)ddEl.style.display='none';}
}

function saleSrchParts(q){
  var dd = document.getElementById('saleItemResults') || document.getElementById('salePDD');
  if(!dd)return;
  if(!q||q.length<1){dd.innerHTML='';return;}
  var ql = q.toLowerCase();
  var hits = inv.filter(function(p){return invMatchesQ(p,ql);}).slice(0,8); /* V27.1 normalized */
  if(!hits.length){
    dd.innerHTML='<div style="font-size:13px;color:var(--tx3);padding:8px 0">No match — <button onclick="saleAddCustom(\''+q.replace(/'/g,'')+'\''+')" style="background:none;border:none;color:var(--red);font-size:13px;cursor:pointer;font-family:var(--fn);text-decoration:underline">add custom</button></div>';
    return;
  }
  dd.innerHTML = hits.map(function(p){
    var qty = parseFloat(p.qty_on_hand||0);
    var sell = invSell(p);
    var nums=invAllNums(p).join(' \u00b7 ');
    return '<div data-pid="'+p.id+'" onclick="saleAddPart(this.dataset.pid)" style="background:var(--sf);border:1.5px solid var(--bd2);border-radius:var(--rs);padding:10px 12px;margin-bottom:6px;cursor:pointer;display:flex;align-items:center;gap:10px">'+
      '<div style="flex:1;min-width:0"><div style="font-size:14px;font-weight:600">'+(p.name||'Part')+'</div>'+
      (nums?'<div style="font-size:10px;color:var(--tx3);font-family:var(--mo)">'+nums+'</div>':'')+
      '<div style="font-size:11px;color:var(--tx3)">Stock: '+qty+'</div></div>'+
      '<div style="font-size:15px;font-weight:700;color:var(--grn)">$'+sell.toFixed(2)+'</div>'+
      '<div style="color:var(--red);font-size:22px;line-height:1">+</div>'+
    '</div>';
  }).join('');
}

function saleAddPart(id){
  var p = inv.find(function(x){return x.id===id;});
  if(!p)return;
  var existing = saleItems.find(function(s){return s.invId===id;});
  if(existing){existing.qty++;} 
  else {
    saleItems.push({invId:id,name:p.name,qty:1,price:invSell(p),partNum:p.part||p.oem||''});
  }
  var psrch = document.getElementById('saleItemSearch') || document.getElementById('salePsrch');
  if(psrch) psrch.value='';
  var pdd = document.getElementById('saleItemResults') || document.getElementById('salePDD');
  if(pdd) pdd.innerHTML='';
  renderSaleItems();
}

function saveCustomSaleItem(){
  var name=(document.getElementById('sc_nm').value||'').trim();
  if(!name){toast('Enter name','er');return;}
  saleItems.push({invId:null,name:name,qty:parseInt(document.getElementById('sc_qty').value)||1,price:parseFloat(document.getElementById('sc_pr').value)||0,partNum:''});
  closeM();
  var _psrch=document.getElementById('saleItemSearch')||document.getElementById('salePsrch');
  var _pdd=document.getElementById('saleItemResults')||document.getElementById('salePDD');
  if(_psrch)_psrch.value='';
  if(_pdd)_pdd.innerHTML='';
  renderSaleItems();
}

function renderSaleItems(){
  var el = document.getElementById('saleCart') || document.getElementById('saleItems');
  var totEl = document.getElementById('saleTotals');
  if(!el)return;
  if(!saleItems.length){
    el.innerHTML='<div style="text-align:center;color:var(--tx3);padding:20px;font-size:13px">Search above to add items</div>';
    if(totEl) totEl.innerHTML='<div style="text-align:center;color:var(--tx3);font-size:13px;padding:8px">Add items to see totals</div>';
    return;
  }
  var sub = 0;
  var h = '';
  saleItems.forEach(function(item, idx){
    var total = item.qty * item.price;
    sub += total;
    h += '<div style="background:var(--sf);border:1.5px solid var(--bd2);border-radius:var(--r);padding:10px 12px;margin-bottom:8px">';
    // Row 1: name + remove
    h += '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:8px">';
    h += '<div style="font-size:14px;font-weight:600;flex:1;min-width:0">'+item.name+'</div>';
    h += '<button data-idx="'+idx+'" onclick="saleRemoveItem(this.dataset.idx)" style="background:none;border:none;color:var(--tx3);font-size:18px;cursor:pointer;padding:0;line-height:1;flex-shrink:0">✕</button>';
    h += '</div>';
    // Row 2: qty controls + price input + line total
    h += '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">';
    // qty stepper
    h += '<button data-idx="'+idx+'" onclick="saleAdjQty(this.dataset.idx,-1)" style="width:30px;height:30px;background:var(--sf2);border:1.5px solid var(--bd2);border-radius:6px;font-size:18px;cursor:pointer;color:var(--tx1);display:flex;align-items:center;justify-content:center">−</button>';
    h += '<span style="font-size:16px;font-weight:700;min-width:22px;text-align:center">'+item.qty+'</span>';
    h += '<button data-idx="'+idx+'" onclick="saleAdjQty(this.dataset.idx,1)" style="width:30px;height:30px;background:var(--sf2);border:1.5px solid var(--bd2);border-radius:6px;font-size:18px;cursor:pointer;color:var(--tx1);display:flex;align-items:center;justify-content:center">+</button>';
    // editable price
    h += '<div style="display:flex;align-items:center;gap:4px;flex:1;min-width:80px">';
    h += '<span style="font-size:12px;color:var(--tx3);flex-shrink:0">@ $</span>';
    h += '<input type="number" step="0.01" min="0" data-idx="'+idx+'" value="'+item.price.toFixed(2)+'"'+
         ' oninput="salePriceEdit(this.dataset.idx,this.value)"'+
         ' style="width:68px;background:var(--sf2);border:1.5px solid var(--bd2);border-radius:6px;padding:5px 6px;font-size:14px;font-weight:700;font-family:var(--mo);color:var(--tx1);text-align:right">';
    h += '</div>';
    // line total
    h += '<div style="font-size:15px;font-weight:800;font-family:var(--mo);color:var(--tx1);min-width:52px;text-align:right">$'+total.toFixed(2)+'</div>';
    h += '</div>';
    h += '</div>';
  });
  el.innerHTML = h;
  updateSaleTotals(sub);
}

function updateSaleTotals(sub){
  if(sub===undefined) sub=saleItems.reduce(function(s,i){return s+i.qty*i.price;},0);
  var tax = parseFloat((sub * 0.08625).toFixed(2));
  var total = parseFloat((sub + tax).toFixed(2));
  // old screen element IDs
  var subEl=document.getElementById('saleSubtotal');if(subEl)subEl.textContent='$'+sub.toFixed(2);
  var taxEl=document.getElementById('saleTax');if(taxEl)taxEl.textContent='$'+tax.toFixed(2);
  var totEl2=document.getElementById('saleTotal');if(totEl2)totEl2.textContent='$'+total.toFixed(2);
  // new screen totals div
  var totEl=document.getElementById('saleTotals');
  if(totEl) totEl.innerHTML=
    '<div class="tot-row"><span style="color:var(--tx3)">Subtotal</span><span>$'+sub.toFixed(2)+'</span></div>'+
    '<div class="tot-row"><span style="color:var(--tx3)">Tax (8.625%)</span><span>$'+tax.toFixed(2)+'</span></div>'+
    '<div class="tot-row fin"><span>Total</span><span style="color:var(--grn)">$'+total.toFixed(2)+'</span></div>';
}

function salePriceEdit(idx, val){
  var i = parseInt(idx);
  if(!saleItems[i])return;
  saleItems[i].price = Math.max(0, parseFloat(val)||0);
  // update just the line total and grand totals without full re-render (keeps focus)
  var sub = saleItems.reduce(function(s,item){return s+item.qty*item.price;},0);
  updateSaleTotals(sub);
  // also update the line total display for this item
  var rows = (document.getElementById('saleCart')||document.getElementById('saleItems')||{}).children;
  if(rows&&rows[i]){
    var lineEl=rows[i].querySelector('[style*="min-width:52px"]');
    if(lineEl)lineEl.textContent='$'+(saleItems[i].qty*saleItems[i].price).toFixed(2);
  }
}

function saleAdjQty(idx, delta){
  var i = parseInt(idx);
  if(!saleItems[i])return;
  saleItems[i].qty = Math.max(1, saleItems[i].qty + delta);
  renderSaleItems();
}

function saleRemoveItem(idx){
  saleItems.splice(parseInt(idx), 1);
  renderSaleItems();
}

function getSaleTotals(){
  var sub = saleItems.reduce(function(s,item){return s + item.qty * item.price;}, 0);
  var tax = sub * 0.08625;
  return {sub:sub, tax:tax, total:sub+tax};
}

async function recordSalePayment(){
  if(!saleItems.length){toast('Add items first','er');return;}
  var t = getSaleTotals();
  var custName = saleCustId ? (custs.find(function(c){return c.id===saleCustId;})||{}).name||'Walk-in' : (saleCustObj&&saleCustObj.walkIn?saleCustObj.name:'Walk-in');
  openM('<div class="mt">Record Payment</div>'+
    '<div class="ms">Total: <strong style="color:var(--grn)">$'+t.total.toFixed(2)+'</strong> — '+custName+'</div>'+
    '<div class="mf">'+
    '<div><div class="mlbl">Method</div><select class="mi" id="sp_mth"><option>Cash</option><option>Check</option><option>Credit Card</option><option>Zelle</option><option>Venmo</option></select></div>'+
    '<div><div class="mlbl">Note (optional)</div><input class="mi" id="sp_note" placeholder="Check #, etc."></div>'+
    '</div>'+
    '<div class="mb"><button class="mc-btn" onclick="closeM()">Cancel</button>'+
    '<button class="mo-btn" id="spOk" onclick="saveSalePayment()">Paid</button></div>');
}

async function saveSalePayment(){
  var btn=document.getElementById('spOk');btn.disabled=true;btn.textContent='Saving...';
  var t = getSaleTotals();
  var method = document.getElementById('sp_mth').value;
  var note = (document.getElementById('sp_note').value||'').trim();
  try{
    // Create a WO for this sale
    var nextInv = (Math.max.apply(null, wos.map(function(w){return w.invoice_number||0;})) || 1000) + 1;
    var md = {};
    // Use a generic "sale" equipment entry or no equipment
    var machKey = 'sale_'+Date.now();
    md[machKey] = {parts: saleItems.map(function(s){return {name:s.name,qty:s.qty,price:s.price,partNum:s.partNum||'',invId:s.invId};}), labor:[]};
    var wo = await post('work_orders',{
      customer_id: saleCustId||null,
      status:'Invoiced',
      invoice_status:'paid',
      invoice_number: nextInv,
      machines_data: JSON.stringify(md),
      problem: 'Parts sale — '+saleItems.map(function(s){return s.name;}).join(', ')
    });
    var woRec = Array.isArray(wo)?wo[0]:wo;
    if(woRec&&woRec.id){
      var _qs_pmt=await post('payments',{work_order_id:woRec.id,amount:t.total,method:method,note:note||null});
      if(_qs_pmt&&_qs_pmt[0])payments.push(_qs_pmt[0]);
      // Deduct inventory
      for(var i=0;i<saleItems.length;i++){
        var s=saleItems[i];
        if(s.invId){
          var p=inv.find(function(x){return x.id===s.invId;});
          if(p){
            var newQty=Math.max(0,parseFloat(p.qty_on_hand||0)-s.qty);
            var newTruck=Math.max(0,parseFloat(p.qty_truck||0)-s.qty);
            await patch('inventory',{qty_on_hand:newQty,qty_truck:Math.max(0,newTruck),sold_qty:parseFloat(p.sold_qty||0)+s.qty},'?id=eq.'+s.invId);
            p.qty_on_hand=newQty;p.qty_truck=Math.max(0,newTruck);
          }
        }
      }
      wos.unshift(woRec);
      saleNum = nextInv;
      closeM();
      toast('Sale recorded ✓ INV-'+nextInv,'ok');
      // Offer to print
      setTimeout(function(){printSaleReceipt(woRec);},400);
    }
  }catch(e){toast('Failed: '+e.message,'er');btn.disabled=false;btn.textContent='Paid';}
}

