async function pushSaleToQBO(){
  if(!saleItems.length){toast('Add items first','er');return;}
  toast('Pushing to QuickBooks...','');
  try{
    var t = getSaleTotals();
    var c = saleCustId ? custs.find(function(x){return x.id===saleCustId;}) : (saleCustObj&&saleCustObj.walkIn?saleCustObj:null);
    var nextInv = (Math.max.apply(null, wos.map(function(w){return w.invoice_number||0;})) || 1000) + 1;
    var invNum = 'INV-'+nextInv;
    var today = new Date().toISOString().split('T')[0];
    var lineItems = saleItems.map(function(s){
      var invItem=s.invId?inv.find(function(i){return i.id===s.invId;}):null;
      var itype=invItem?invItem.item_type:'Non-Stock';
      var itemName=itype==='Stock'?'Parts - Stock':itype==='Service'?'Labor':'Parts - Non-Stock';
      return {item_name:itemName, description:s.name+(s.partNum?' #'+s.partNum:''), qty:s.qty, rate:s.price, amount:parseFloat((s.qty*s.price).toFixed(2))};
    });
    var payload={action:'push_invoice',invoice:{invoice_number:invNum,customer_name:c?c.name:'Walk-in Customer',customer_phone:c?c.phone||'':'',date:today,due_date:today,memo:'Parts sale',tax_amount:parseFloat(t.tax.toFixed(2)),line_items:lineItems}};
    var data=await qboCall(payload);
    if(data.error||data.qbo_disconnected||data.qbo_bad_credentials||data.app_signed_out||data.network_error){_qboFailed(data,'this parts sale');return;}
    toast('Pushed to QBO — total $'+parseFloat(data.qbo_total||0).toFixed(2),'ok');
  }catch(e){toast('Push failed: '+e.message,'er');}
}

function openSaleReceipt(){navTo('S_sale');}

function initSaleReceipt(){
  saleItems = [];
  saleCart = [];
  saleCustId = null;
  saleCustObj = null;
  var srch = document.getElementById('saleCustSearch'); if(srch) srch.value='';
  var res  = document.getElementById('saleCustResults'); if(res) res.innerHTML='';
  var sel  = document.getElementById('saleCustSelected'); if(sel) sel.style.display='none';
  var iSrch = document.getElementById('saleItemSearch'); if(iSrch) iSrch.value='';
  var iRes  = document.getElementById('saleItemResults'); if(iRes) iRes.innerHTML='';
  var custName = document.getElementById('saleCustomName'); if(custName) custName.value='';
  var custPrice = document.getElementById('saleCustomPrice'); if(custPrice) custPrice.value='';
  renderSaleItems();
}

function saleSrchItem(q){
  var dd = document.getElementById('saleItemResults') || document.getElementById('salePDD');
  if(!dd) return;
  if(!q||q.length<1){dd.innerHTML='';return;}
  var ql = q.toLowerCase();
  var hits = inv.filter(function(p){return invMatchesQ(p,ql);}).slice(0,8); /* V27.1 normalized */
  if(!hits.length){
    dd.innerHTML='<div style="font-size:13px;color:var(--tx3);padding:6px 0">No match found</div>';
    return;
  }
  dd.innerHTML = hits.map(function(p){
    var qty  = parseFloat(p.qty_on_hand||0);
    var sell = invSell(p);
    var nums=invAllNums(p).join(' \u00b7 ');
    return '<div data-pid="'+p.id+'" onclick="saleAddPart(this.dataset.pid)" style="background:var(--sf2);border:1.5px solid var(--bd2);border-radius:var(--rs);padding:9px 12px;margin-bottom:6px;cursor:pointer;display:flex;align-items:center;gap:10px">'+
      '<div style="flex:1;min-width:0"><div style="font-size:14px;font-weight:600">'+(p.name||'Part')+'</div>'+
      (nums?'<div style="font-size:10px;color:var(--tx3);font-family:var(--mo)">'+nums+'</div>':'')+
      '<div style="font-size:11px;color:var(--tx3)">Stock: '+qty+'</div></div>'+
      '<div style="font-size:15px;font-weight:700;color:var(--grn)">$'+sell.toFixed(2)+'</div>'+
      '<div style="color:var(--red);font-size:22px;line-height:1;margin-left:4px">+</div>'+
    '</div>';
  }).join('');
}

function addSaleCustomItem(){
  var nameEl  = document.getElementById('saleCustomName');
  var priceEl = document.getElementById('saleCustomPrice');
  var name  = (nameEl ? nameEl.value : '').trim();
  var price = parseFloat(priceEl ? priceEl.value : 0) || 0;
  if(!name){toast('Enter item name','er');if(nameEl)nameEl.focus();return;}
  saleItems.push({invId:null, name:name, qty:1, price:price, partNum:''});
  if(nameEl) nameEl.value='';
  if(priceEl) priceEl.value='';
  renderSaleItems();
}

async function saveSaleReceipt(){
  if(!saleItems.length){toast('Add items first','er');return;}
  await recordSalePayment();
}

async function saveSaleJpg(woRec){
  if(!saleItems.length&&!woRec){toast('Add items first','er');return;}
  toast('Generating JPG…','');
  try{
    // Build the same clean HTML that printSaleReceipt generates
    var t=getSaleTotals();
    var c=saleCustId?custs.find(function(x){return x.id===saleCustId;}):null;
    if(!c&&woRec&&woRec.customer_id)c=cMap[woRec.customer_id];
    var invNum=woRec&&woRec.invoice_number?'INV-'+woRec.invoice_number:(saleNum?'INV-'+saleNum:'RECEIPT');
    var dateStr=new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});
    var items=saleItems.length?saleItems:[];
    if(!items.length&&woRec){
      try{var md=JSON.parse(woRec.machines_data||'{}');Object.values(md).forEach(function(d){(d.parts||[]).forEach(function(p){items.push({name:p.name,qty:p.qty,price:p.price});});});}catch(e){}
      if(items.length){var sub2=items.reduce(function(s,i){return s+i.qty*i.price;},0);t={sub:sub2,tax:sub2*0.08625,total:sub2*1.08625};}
    }

    var itemsHtml=items.map(function(s){
      return '<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #f0f0f0;font-size:13px">'+
        '<div style="flex:1"><div style="font-weight:600">'+s.name+'</div>'+
        '<div style="font-size:11px;color:#888">'+s.qty+' × $'+s.price.toFixed(2)+'</div></div>'+
        '<div style="font-weight:600;white-space:nowrap;padding-left:12px">$'+(s.qty*s.price).toFixed(2)+'</div></div>';
    }).join('');

    var html='<!DOCTYPE html><html><head><meta charset="utf-8"><style>'+
      '*{margin:0;padding:0;box-sizing:border-box}'+
      'body{font-family:Arial,Helvetica,sans-serif;color:#111;background:#fff;padding:32px;width:480px}'+
      '</style></head><body>'+
      '<div style="border-bottom:2px solid #e85d3a;padding-bottom:12px;margin-bottom:16px">'+
        '<img src=\"data:image/jpeg;base64,\" style=\"height:60px;width:auto\" alt=\"DG Equipment\">'+
        '<div style="font-size:12px;color:#555;margin-top:3px">Oceanside, NY &nbsp;·&nbsp; (516) 350-8898</div>'+
        '<div style="font-size:12px;color:#555">dgequipmentservices@gmail.com</div>'+
      '</div>'+
      '<div style="margin-bottom:14px">'+
        '<div style="font-size:15px;font-weight:700;color:#e85d3a;margin-bottom:2px">'+invNum+'</div>'+
        '<div style="font-size:12px;color:#555">'+dateStr+'</div>'+
        (c?'<div style="font-size:14px;font-weight:600;margin-top:4px">'+c.name+(c.phone?' &nbsp;·&nbsp; '+c.phone:'')+'</div>':'')+
      '</div>'+
      '<div style="margin-bottom:14px">'+
        '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:#888;border-bottom:1px solid #ddd;padding-bottom:4px;margin-bottom:8px">Items</div>'+
        itemsHtml+
      '</div>'+
      '<div style="border-top:1px solid #ddd;padding-top:10px">'+
        '<div style="display:flex;justify-content:space-between;padding:3px 0;font-size:13px"><span style="color:#888">Subtotal</span><span>$'+t.sub.toFixed(2)+'</span></div>'+
        '<div style="display:flex;justify-content:space-between;padding:3px 0;font-size:13px"><span style="color:#888">Tax (8.625%)</span><span>$'+t.tax.toFixed(2)+'</span></div>'+
        '<div style="display:flex;justify-content:space-between;padding:6px 0;font-size:16px;font-weight:800;border-top:1px solid #ddd;margin-top:4px"><span>Total</span><span style="color:#2e7d32">$'+t.total.toFixed(2)+'</span></div>'+
      '</div>'+
      '<div style="text-align:center;margin:16px 0">'+
        '<div style="display:inline-block;font-size:22px;font-weight:900;color:#2e7d32;border:3px solid #2e7d32;border-radius:6px;padding:6px 20px;transform:rotate(-3deg);letter-spacing:.1em">PAID IN FULL</div>'+
      '</div>'+
      '<div style="font-size:10px;color:#999;text-align:center;line-height:1.7;border-top:1px solid #eee;padding-top:10px">'+
        'Thank you for your business! &nbsp;·&nbsp; 30-day warranty on parts &amp; labor.'+
      '</div>'+
      '</body></html>';

    // Render in hidden iframe, capture with html2canvas
    var iframe=document.createElement('iframe');
    iframe.style.cssText='position:fixed;left:-9999px;top:0;width:512px;height:1px;border:none;visibility:hidden';
    document.body.appendChild(iframe);
    await new Promise(function(resolve){iframe.onload=resolve;iframe.srcdoc=html;});
    await new Promise(function(r){setTimeout(r,300);});
    var iDoc=iframe.contentDocument||iframe.contentWindow.document;
    var fullH=iDoc.body.scrollHeight;
    iframe.style.height=fullH+'px';
    iframe.style.visibility='visible';
    await new Promise(function(r){setTimeout(r,100);});

    if(!window.html2canvas){
      await new Promise(function(resolve,reject){
        var s=document.createElement('script');
        s.src='https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
        s.onload=resolve;s.onerror=reject;
        document.head.appendChild(s);
      });
    }
    var canvas=await html2canvas(iDoc.body,{backgroundColor:'#ffffff',scale:2,useCORS:true,logging:false,windowWidth:512,windowHeight:fullH});
    document.body.removeChild(iframe);

    var custName=c?c.name.replace(/[^a-z0-9]/gi,'-').toLowerCase():'sale';
    var link=document.createElement('a');
    link.download=invNum+'-'+custName+'.jpg';
    link.href=canvas.toDataURL('image/jpeg',0.95);
    link.click();
    toast('Saved '+invNum+'.jpg ✓','ok');
  }catch(e){toast('JPG failed: '+e.message,'er');}
}


function saleAddCustom(name){
  openM('<div class="mt">Add Custom Item</div>'+
    '<div class="mf">'+
    '<div><div class="mlbl">Name *</div><input class="mi" id="sc_nm" value="'+name.replace(/"/g,'&quot;')+'"></div>'+
    '<div class="mr">'+
      '<div style="flex:1"><div class="mlbl">Qty</div><input class="mi" id="sc_qty" type="number" min="1" value="1"></div>'+
      '<div style="flex:1"><div class="mlbl">Price $</div><input class="mi" id="sc_pr" type="number" step="0.01" placeholder="0.00"></div>'+
    '</div>'+
    '</div>'+
    '<div class="mb"><button class="mc-btn" onclick="closeM()">Cancel</button>'+
    '<button class="mo-btn" onclick="saveCustomSaleItem()">Add</button></div>');
  setTimeout(function(){var el=document.getElementById('sc_pr');if(el){el.focus();el.select();}},150);
}


